import React from "react";
export const useFeedbackToastState = () => {
    const removedToastId = React.useRef(null);
    const [toasts, setToasts] = React.useState([]);
    const [toastsQueue, setToastsQueue] = React.useState([]);
    const [toastsAnimation, setToastsAnimation] = React.useState([]);
    const [apiToastActions, setApiToastActions] = React.useState([]);
    return {
        toasts,
        setToasts,
        toastsQueue,
        setToastsQueue,
        toastsAnimation,
        setToastsAnimation,
        removedToastId,
        apiToastActions,
        setApiToastActions
    };
};
